// Generated by scripts/sync-aiiolar-sheet.mjs from aiiolar. Do not edit by hand; run npm run sync:aiiolar-sheet.
'use client'

import { useEffect, useRef, useState } from 'react'
import type { HbIcons } from './types'
import { In } from './In'
import { useReducedMotion } from './motion'
import styles from './handbook.module.css'

/** A row of steps: tap one to light the path up to it, or play through. Reduced motion and `compact` (a notebook sheet) show every step, with no controls. */
export function Flow({ nodes, icons, compact }: { nodes: { text: string; sub?: string; ink?: string }[]; icons: HbIcons; compact?: boolean }) {
  const reduce = useReducedMotion()
  const [upTo, setUpTo] = useState(0)
  const timer = useRef<number | undefined>(undefined)
  useEffect(() => () => window.clearInterval(timer.current), [])
  const shown = reduce || compact ? nodes.length - 1 : upTo
  const play = () => {
    window.clearInterval(timer.current)
    setUpTo(0)
    let k = 0
    timer.current = window.setInterval(() => { k++; setUpTo(k); if (k >= nodes.length - 1) window.clearInterval(timer.current) }, 700)
  }
  return (
    <div>
      <ol className={styles.flow}>
        {nodes.map((n, i) => {
          const label = <><In text={n.text} icons={icons} />{n.sub && <In as="span" className={styles.small} text={n.sub} icons={icons} />}</>
          return (
          <li key={i} data-step data-on={i <= shown || undefined} className={n.ink ? `ink-${n.ink}` : undefined}>
            {compact ? <span className={styles.fnode}>{label}</span> : <button type="button" onClick={() => setUpTo(i)}>{label}</button>}
          </li>
          )
        })}
      </ol>
      {!reduce && !compact && nodes.length > 1 && (
        <div className={styles.ctl}>
          <button type="button" onClick={play}>▶ Play</button>
          <button type="button" onClick={() => setUpTo(nodes.length - 1)}>Show all</button>
        </div>
      )}
    </div>
  )
}
